"use client"

import type { ReactNode } from "react"
import { useRef } from "react"

import { Badge } from "@/components/ui/badge"

import { useHiw2V2Animations } from "../hooks/use-hiw2-v2-animations"
import { STEP_LABEL_BADGE_VARIANT, steps } from "../lib/steps"
import StepCard from "./step-card"

type StepsGridProps = {
  title: ReactNode
}

export default function StepsGrid({ title }: StepsGridProps) {
  const titleRef = useRef<HTMLDivElement>(null)
  const cardRefs = useRef<(HTMLDivElement | null)[]>([])

  useHiw2V2Animations({
    title: titleRef,
    cards: cardRefs,
  })

  return (
    <div className="mx-auto max-w-6xl px-4">
      <div ref={titleRef} className="mb-12 md:mb-16">
        {title}
      </div>

      <div className="grid grid-cols-1 gap-10 md:grid-cols-3 md:gap-8 lg:gap-14">
        {steps.map((step, i) => (
          <div
            key={step.id}
            ref={(el) => {
              cardRefs.current[i] = el
            }}
          >
            <Badge variant={STEP_LABEL_BADGE_VARIANT} className="uppercase">
              {step.label}
            </Badge>

            <StepCard step={step} />
          </div>
        ))}
      </div>
    </div>
  )
}

import { CheckCircle2 } from "lucide-react"

import type { Step } from "../lib/steps"

type Props = {
  step: Step
}

export default function StepCard({ step }: Props) {
  return (
    <div className="flex flex-col gap-4 pt-4">
      <h3 className="text-xl leading-snug font-medium tracking-tight text-foreground">
        {step.title}
      </h3>

      <ul className="flex flex-col gap-3">
        {step.features.map((feature, index) => (
          <li
            key={index}
            data-hiw2-feature=""
            className="flex items-start gap-3 text-sm leading-relaxed text-muted-foreground"
          >
            <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 fill-foreground stroke-background text-foreground" />
            <span>{feature}</span>
          </li>
        ))}
      </ul>
    </div>
  )
}

"use client"

import { type RefObject, useLayoutEffect, useRef } from "react"

import gsap from "gsap"
import { ScrollTrigger } from "gsap/ScrollTrigger"

gsap.registerPlugin(ScrollTrigger)

export type Hiw2V2Refs = {
  title: RefObject<HTMLElement | null>
  cards: RefObject<(HTMLDivElement | null)[]>
}

export function useHiw2V2Animations(refs: Hiw2V2Refs) {
  const refsRef = useRef(refs)
  useLayoutEffect(() => {
    refsRef.current = refs
  })

  useLayoutEffect(() => {
    let ctx: gsap.Context | null = null
    const r = () => refsRef.current

    const cardEls = (r().cards.current ?? []).filter(Boolean) as HTMLElement[]
    if (!cardEls.length) return

    ctx = gsap.context(() => {
      const titleEl = r().title.current

      if (titleEl) {
        gsap.set(titleEl, { y: 28, opacity: 0 })
        gsap.to(titleEl, {
          y: 0,
          opacity: 1,
          duration: 0.8,
          ease: "power3.out",
          scrollTrigger: {
            trigger: titleEl,
            start: "top 88%",
            once: true,
                      },
        })
      }

      cardEls.forEach((card) => {
        gsap.set(card, { y: 20, opacity: 0 })
        gsap.to(card, {
          y: 0,
          opacity: 1,
          duration: 0.6,
          ease: "power3.out",
          scrollTrigger: {
            trigger: card,
            start: "top 84%",
            once: true,
          },
        })
      })

      cardEls.forEach((card, i) => {
        const features = Array.from(
          card.querySelectorAll<HTMLElement>("[data-hiw2-feature]")
        )
        if (!features.length) return

        gsap.set(features, { x: -12, opacity: 0 })
        gsap.to(features, {
          x: 0,
          opacity: 1,
          stagger: 0.075,
          duration: 0.44,
          ease: "power2.out",
          delay: 0.2 + i * 0.08,
          scrollTrigger: {
            trigger: card,
            start: "top 84%",
            once: true,
                      },
        })
      })

      requestAnimationFrame(() => {
        ScrollTrigger.refresh()
      })
    })

    return () => {
      ctx?.revert()
    }
  }, [])
}

export const STEP_LABEL_BADGE_VARIANT = "outline" as const

